catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	console.log('onChange triggered');
    console.log('newValue:', newValue);
    if (isLoading || newValue == '') return;

    var ga = new GlideAjax('EventUtils'); // Script Include name
    ga.addParam('sysparm_name', 'getEventDetails'); // function name
    ga.addParam('eventId', newValue); // event sys_id

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.addErrorMessage(data.error);
        } else {
            var msg = 'Event Details:<br>' +
                      '<b>Name:</b> ' + data.event_name + '<br>' +
                      '<b>Date:</b> ' + data.event_date + '<br>' +
                      '<b>Location:</b> ' + data.location + '<br>' +
                      '<b>Planner:</b> ' + data.planner;

            g_form.addInfoMessage(msg);

            // Optional: set to other form fields if needed
            // g_form.setValue('u_event_name', data.event_name);
        }
    });
}
